var STORAGE_KEY="ayrix-theme";function getPreferredTheme(){const e=localStorage.getItem(STORAGE_KEY);return e==="light"||e==="dark"?e:window.matchMedia("(prefers-color-scheme: light)").matches?"light":"dark"}function applyTheme(e){document.documentElement.dataset.theme=e,localStorage.setItem(STORAGE_KEY,e)}function initThemeToggle(){applyTheme(getPreferredTheme()),document.querySelectorAll("#theme-toggle, #theme-toggle-mobile").forEach(e=>{e.addEventListener("click",()=>{const e=document.documentElement.dataset.theme==="dark"?"light":"dark";applyTheme(e)})})}function markActiveNav(){const e=window.location.pathname.replace(/\/$/,"")||"/";document.querySelectorAll(".app-nav a, .app-tabbar a").forEach(t=>{const n=t.getAttribute("href")?.replace(/\/$/,"")||"/",s=n===e||n!=="/"&&e.startsWith(n);t.classList.toggle("is-active",s),s?t.setAttribute("aria-current","page"):t.removeAttribute("aria-current")})}initThemeToggle(),markActiveNav()